"""Extract authentic race-footstep variants from the user's local Uma race bank."""
import hashlib
import json
import re
import struct
import subprocess
import wave
import numpy as np
from inspect_assets import ROOT
from read_cri_audio import utf,awb

FOLDER=ROOT/'modding/uma-steam/audio'

def cue_waves(header,name):
    tables={key:utf(header[key])[1] for key in ['CueNameTable','CueTable','WaveformTable','SynthTable','SequenceTable','TrackTable','TrackEventTable']}
    names=[r for r in tables['CueNameTable'] if r['CueName']==name]
    if len(names)!=1:raise ValueError('Cue absent or ambiguous')
    cue=tables['CueTable'][names[0]['CueIndex']];found=[]
    def resolve(kind,index,path=()):
        if len(path)>16 or (kind,index) in path:raise ValueError('CRI cue cycle or excessive depth')
        path=path+((kind,index),)
        if kind==1:
            row=tables['WaveformTable'][index]
            if row['Streaming'] or row['MemoryAwbId']==65535:raise ValueError('Expected embedded race footstep')
            found.append({'waveform_index':index,'awb_id':row['MemoryAwbId'],'rate':row['SamplingRate'],'channels':row['NumChannels'],'samples':row['NumSamples']})
        elif kind==2:
            items=tables['SynthTable'][index]['ReferenceItems']
            if len(items)%4:raise ValueError('Truncated CRI synth reference')
            for k,i in struct.iter_unpack('>HH',items):
                if k:resolve(k,i,path)
        elif kind==3:
            row=tables['SequenceTable'][index];tracks=row['TrackIndex']
            if len(tracks)!=row['NumTracks']*2:raise ValueError('Track count mismatch')
            for (track,) in struct.iter_unpack('>H',tracks):
                command=tables['TrackEventTable'][tables['TrackTable'][track]['EventIndex']]['Command'];at=0
                while at<len(command):
                    if at+3>len(command):raise ValueError('Truncated CRI command')
                    opcode,length=struct.unpack_from('>HB',command,at);at+=3
                    if at+length>len(command):raise ValueError('Truncated CRI command payload')
                    if opcode in (2000,2003):
                        if length<4:raise ValueError('Invalid CRI note event')
                        k,i=struct.unpack_from('>HH',command,at);resolve(k,i,path)
                    at+=length
        else:raise ValueError(f'Unsupported CRI reference kind {kind}')
    resolve(cue['ReferenceType'],cue['ReferenceIndex'])
    return list({r['awb_id']:r for r in found}.values())

def main():
    bank=FOLDER/'snd_sfx_race_000.acb';data=bank.read_bytes()
    provenance=json.loads((FOLDER/'source.json').read_text())
    if hashlib.sha256(data).hexdigest()!=provenance['sha256']:raise ValueError('Staged race bank changed')
    tool=ROOT/'modding/uma-steam/audio-tools/clhca';reader=json.loads((tool/'source.json').read_text())
    for filename,expected in reader['files'].items():
        if hashlib.sha256((tool/filename).read_bytes()).hexdigest()!=expected:raise ValueError('Pinned HCA reader source changed')
    subprocess.run(['gcc','-std=c11','-O2','-c',str(tool/'clhca.c'),'-o',str(tool/'clhca.o')],check=True)
    subprocess.run(['gcc','-std=c11','-O2','-Wall','-Wextra','-Werror',str(tool/'decode_local.c'),str(tool/'clhca.o'),'-lm','-o',str(tool/'decode-local')],check=True)
    name,rows=utf(data)
    if name!='Header' or len(rows)!=1:raise ValueError('Expected one ACB header')
    header=rows[0];subkey,entries=awb(header['AwbFile']);waves=dict(entries)
    viewer=ROOT/'modding/uma-steam/tools/UmaViewer'
    if subprocess.check_output(['git','-C',str(viewer),'rev-parse','HEAD'],text=True).strip()!='9bc1dd8fcb10ab13c17ada92e005643b463f8e2c':raise ValueError('Pinned UmaViewer reader revision changed')
    config=subprocess.check_output(['git','-C',str(viewer),'show','HEAD:Assets/Scripts/Config.cs'],text=True)
    match=re.search(r'DefaultAudioKeyText\s*=\s*"([0-9A-Fa-f]+)"',config)
    if not match:raise ValueError('Pinned reader audio key absent')
    base=int(match[1],16);key=(base*((subkey<<16)|((~subkey&65535)+2)))&((1<<64)-1)
    decoder=ROOT/'modding/uma-steam/audio-tools/clhca/decode-local';out=FOLDER/'race-footsteps';out.mkdir(exist_ok=True);reports=[]
    for foot,side in [(0,'R'),(1,'L')]:
        cue=f'snd_sfx_race_foot_turf_{side}';variants=cue_waves(header,cue)
        if len(variants)!=10:raise ValueError('Expected original ten-variant footstep cue')
        for variant,entry in enumerate(variants):
            encoded=waves[entry['awb_id']];hca=out/f'wave-{entry["awb_id"]}.hca';pcm=hca.with_suffix('.s16le');hca.write_bytes(encoded)
            process=subprocess.run([str(decoder),str(hca),f'{key:x}',str(pcm)],check=True,capture_output=True,text=True);info=json.loads(process.stdout)
            if (info['rate'],info['channels'],info['frames'])!=(entry['rate'],entry['channels'],entry['samples']):raise ValueError('Decoded HCA metadata differs from WaveformTable')
            resample=subprocess.run(['ffmpeg','-v','error','-f','s16le','-ar',str(info['rate']),'-ac',str(info['channels']),'-i',str(pcm),'-ar','22050','-ac','1','-f','s16le','pipe:1'],check=True,capture_output=True)
            raw=resample.stdout;values=np.frombuffer(raw,'<i2')
            if not len(values) or not np.any(values) or len(raw)>32000:raise ValueError('Footstep empty or too long for runtime')
            path=out/f'hoof-{foot}-{variant}.wav'
            with wave.open(str(path),'wb') as f:f.setnchannels(1);f.setsampwidth(2);f.setframerate(22050);f.writeframes(raw)
            reports.append(dict(entry,foot=foot,variant=variant,cue=cue,file=str(path.relative_to(ROOT)),sha256=hashlib.sha256(path.read_bytes()).hexdigest(),seconds=len(values)/22050,peak=float(np.max(np.abs(values.astype(float))))/32768,key_validation_blocks=info['key_validation_blocks']))
        print('Decoded',cue,len(variants),'original variants',flush=True)
    manifest={'source_bank_sha256':hashlib.sha256(data).hexdigest(),'reader_uma_viewer_commit':subprocess.check_output(['git','-C',str(viewer),'rev-parse','HEAD'],text=True).strip(),'clhca_source':json.loads((decoder.parent/'source.json').read_text()),'samples':reports,'processing':'Original HCA decoded, encoder delay/padding removed, mono 22050 PCM16 conversion; no synthesis, pitch change or amplitude normalization','installed':False}
    (out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print('Prepared',len(reports),'original footstep samples')

if __name__=='__main__':main()

"""Extract local rig, motion and motion-SE bundles without writing Steam sources."""
import hashlib
import importlib.util
import json
from pathlib import Path
import shutil
import subprocess
import sys

ROOT=Path(__file__).resolve().parents[2]
WORK=ROOT/'modding/uma-steam'
sys.path.insert(0,str(WORK/'python-deps'))
import apsw
import UnityPy

SOURCE=Path('/home/nemesis/.local/share/Steam/steamapps/common/UmamusumePrettyDerby/UmamusumePrettyDerby_Data/Persistent')
COMMIT='dca091dad2947d13f99a0510bcccdec82941df0c'
ASSETS={
 'anm_rac_type03_run02_base':'3d/motion/racemain/body/type03/anm_rac_type03_run02_base',
 'anm_rac_type03_run03_base':'3d/motion/racemain/body/type03/anm_rac_type03_run03_base',
 'kitasan-body':'3d/chara/body/bdy1068_00/pfb_bdy1068_00',
 'run02-motion-se':'3d/motionse/racemain/body/type03/anm_rac_type03_run02_base',
}

def digest(data):return hashlib.sha256(data).hexdigest()

def main():
    repo=WORK/'tools/UmaExporter'
    if subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'],text=True).strip()!=COMMIT:raise ValueError('Reader revision changed')
    helper=repo/'src/core/decryptor.py'
    if helper.read_bytes()!=subprocess.check_output(['git','-C',str(repo),'show',f'{COMMIT}:src/core/decryptor.py']):raise ValueError('Reader source changed')
    spec=importlib.util.spec_from_file_location('uma_decryptor_helper',helper);decryptor=importlib.util.module_from_spec(spec);spec.loader.exec_module(decryptor)
    snapshot=WORK/'meta.snapshot';shutil.copyfile(SOURCE/'meta',snapshot)
    db=apsw.Connection(str(snapshot),flags=apsw.SQLITE_OPEN_READONLY)
    db.execute("PRAGMA cipher='chacha20'");db.execute('PRAGMA cipher_page_size=4096')
    db.execute(f'''PRAGMA hexkey='{decryptor.get_db_hex_key("global")}' ''')
    output=WORK/'bundles';output.mkdir(exist_ok=True)
    for name,logical in ASSETS.items():
        rows=list(db.execute('SELECT h,e FROM a WHERE n=?',(logical,)))
        if len(rows)!=1:raise ValueError(f'Catalog entry not unique: {logical}')
        hashed,key=rows[0]
        if not hashed.isalnum():raise ValueError('Invalid catalog filename')
        source=SOURCE/'dat'/hashed[:2]/hashed;original=source.read_bytes()
        decoded=bytes(decryptor.decrypt_bundle(bytearray(original),key=key,base_keys=decryptor.ASSET_BASE_KEYS_JAPAN))
        if not decoded.startswith(b'UnityFS\0'):raise ValueError('Invalid bundle header')
        env=UnityPy.load(decoded)
        if name=='kitasan-body':
            data=[{'path_id':obj.path_id,'type':obj.type.name,'data':obj.read_typetree()} for obj in env.objects if obj.type.name in ('GameObject','Transform','Avatar','Animator')]
            if sum(x['type']=='Avatar' for x in data)!=1:raise ValueError('Expected single source avatar')
            destination=output/'kitasan-body-rig.json'
        elif name=='run02-motion-se':
            events=[obj.read_typetree() for obj in env.objects if obj.type.name=='MonoBehaviour']
            events=[item for item in events if item.get('m_Name')=='anm_rac_type03_run02_base' and 'KeyframeArray' in item]
            if len(events)!=1:raise ValueError('Unexpected motion sound-event object')
            data=events[0];destination=output/(name+'.json')
        else:
            clips=[obj.read_typetree() for obj in env.objects if obj.type.name=='AnimationClip']
            if len(clips)!=1 or clips[0]['m_Name']!=name:raise ValueError('Unexpected animation clip')
            data=clips[0];destination=output/(name+'.json')
        if source.read_bytes()!=original:raise ValueError('Steam source changed during extraction')
        (output/(name+'.unity3d')).write_bytes(decoded)
        destination.write_text(json.dumps(data,ensure_ascii=False)+'\n')
        receipt={'logical_name':logical,'physical_file':str(source),'source_sha256':digest(original),'decoded_sha256':digest(decoded),'catalog_region':'global','bundle_base_keys':'upstream JP constant validated by successful parsing','game_source_unchanged':True,'reader_commit':COMMIT}
        (output/(name+'.source.json')).write_text(json.dumps(receipt,indent=2)+'\n')
        print(name,receipt['source_sha256'],'source unchanged')
    db.close()

if __name__=='__main__':main()

"""Read-only NFSU2 data inspection; only reports are written under modding/."""
import argparse
import hashlib
import json
import struct
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DATA = ('CARS', 'GLOBAL', 'NIS', 'SOUND', 'FRONTEND')
MAX_OUTPUT = 256 * 1024 * 1024


def data_path(relative):
    path = ROOT / relative
    if Path(relative).is_absolute() or '..' in Path(relative).parts:
        raise ValueError('Expected a relative data path')
    if not Path(relative).parts or Path(relative).parts[0] not in DATA:
        raise ValueError('Outside admitted data directories')
    for parent in (path, *path.parents):
        if parent == ROOT:
            break
        if parent.is_symlink():
            raise ValueError('Symlinks are excluded')
    if path.suffix.lower() in ('.exe', '.dll', '.asi'):
        raise ValueError('Executable/plugin excluded')
    path.resolve().relative_to(ROOT)
    return path


def save_json(relative, value):
    path = ROOT / 'modding' / relative
    for parent in (path,*path.parents):
        if parent==ROOT:break
        if parent.is_symlink():raise ValueError('Output symlink excluded')
    path.resolve().relative_to((ROOT / 'modding').resolve())
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('x', encoding='utf-8') as out:
        json.dump(value, out, ensure_ascii=False, indent=2)
        out.write('\n')


def jdlz(data):
    if len(data) < 16 or data[:4] != b'JDLZ':
        raise ValueError('Invalid/truncated JDLZ header')
    size, compressed = struct.unpack_from('<II', data, 8)
    if size > MAX_OUTPUT or compressed < 16 or compressed > len(data):
        raise ValueError('JDLZ size out of bounds')
    if data[4:8] != b'\x02\x10\0\0':
        raise ValueError('Unsupported JDLZ version/flags')
    pos, flags1, flags2 = 16, 1, 1
    out = bytearray()
    def read():
        nonlocal pos
        if pos >= compressed:
            raise ValueError(f'Truncated JDLZ token at {pos:#x}')
        result = data[pos]
        pos += 1
        return result
    while len(out) < size:
        if flags1 == 1:
            flags1 = read() | 0x100
        if flags2 == 1:
            flags2 = read() | 0x100
        if flags1 & 1:
            a, b = read(), read()
            if flags2 & 1:
                length, distance = ((a & 0xf0) << 4 | b) + 3, (a & 15) + 1
            else:
                length, distance = (a & 31) + 3, (b | (a & 0xe0) << 3) + 17
            if distance > len(out) or length > size - len(out):
                raise ValueError('Invalid JDLZ back-reference')
            for _ in range(length):
                out.append(out[-distance])
            flags2 >>= 1
        else:
            out.append(read())
        flags1 >>= 1
    return bytes(out)


def huff(data):
    """EA order-0 Huffman, observed 0x30fb variant; no delta variants guessed."""
    if len(data)<16 or data[:8]!=b'HUFF\x01\x10\0\0':
        raise ValueError('Invalid/unsupported HUFF header')
    size, compressed=struct.unpack_from('<II',data,8)
    if size>MAX_OUTPUT or compressed>len(data)-16:
        raise ValueError('HUFF length out of bounds')
    stream=memoryview(data)[16:16+compressed];bit=0
    def read(count):
        nonlocal bit
        if bit+count>len(stream)*8: raise ValueError('Truncated HUFF bitstream')
        value=0
        for _ in range(count):
            value=(value<<1)|((stream[bit//8]>>(7-bit%8))&1);bit+=1
        return value
    def number():
        if read(1):return read(2)
        n=3
        while not read(1):
            n+=1
            if n>32:raise ValueError('Unterminated HUFF integer')
        value=read(n)+(1<<n)-4
        return value if value<2**31 else value-2**32
    kind=read(16)
    if kind!=0x30fb:raise ValueError(f'Unsupported HUFF stream type {kind:#x}')
    declared=(read(8)<<16)|read(16);clue=read(8)
    if declared!=size:raise ValueError('HUFF inner/outer length mismatch')
    counts=[];base=0;total=0
    for length in range(1,33):
        count=number()
        if not 0<=count<=256:raise ValueError('Invalid HUFF code count')
        base=base*2+count;total+=count;counts.append(count)
        if total>256 or base>1<<length:raise ValueError('Oversubscribed HUFF table')
        if base==1<<length:break
    else:raise ValueError('Incomplete HUFF table')
    symbols=[];used=set();current=255
    for _ in range(total):
        leap=number()+1
        if not 1<=leap<=256-len(used):raise ValueError('Invalid HUFF symbol leap')
        while leap:
            current=(current+1)&255
            if current not in used:leap-=1
        used.add(current);symbols.append(current)
    out=bytearray()
    while len(out)<size:
        code=0;base=0;index=0
        for count in counts:
            code=(code<<1)|read(1)
            if base<=code<base+count:
                symbol=symbols[index+code-base];break
            index+=count;base=(base+count)*2
        else:raise ValueError('Unknown HUFF code')
        if symbol!=clue:out.append(symbol);continue
        length=number()
        if length:
            if length<0 or not out or length>size-len(out):raise ValueError('Invalid HUFF run')
            out.extend(bytes([out[-1]])*length)
        elif read(1):raise ValueError('HUFF premature end')
        else:out.append(read(8))
    return bytes(out)


def chunks(data, start=0, end=None, depth=0):
    end = len(data) if end is None else end
    if depth > 32 or not 0 <= start <= end <= len(data):
        raise ValueError('Chunk nesting/range invalid')
    nodes = []
    while start < end:
        if end - start < 8:
            if any(data[start:end]):
                raise ValueError(f'Truncated chunk header at {start:#x}')
            break
        tag, size = struct.unpack_from('<II', data, start)
        stop = start + 8 + size
        if stop > end:
            raise ValueError(f'Chunk {tag:#x} at {start:#x} exceeds parent {end:#x}')
        node = {'id': f'0x{tag:08x}', 'offset': start, 'payload': start + 8,
                'size': size, 'end': stop, 'offset_mod16': start % 16,
                'payload_mod128': (start + 8) % 128}
        if tag & 0x80000000:
            node['children'] = chunks(data, start + 8, stop, depth + 1)
        nodes.append(node)
        start = stop
    return nodes


def flatten(nodes):
    for node in nodes:
        yield node
        yield from flatten(node.get('children', []))


def inventory():
    result = []
    for folder in DATA:
        for path in sorted((ROOT / folder).rglob('*')):
            if not path.is_file():
                continue
            relative = path.relative_to(ROOT)
            try:
                data_path(relative)
            except ValueError:
                continue
            digest = hashlib.sha256()
            with path.open('rb') as stream:
                head = stream.read(16)
                digest.update(head)
                for block in iter(lambda: stream.read(1024 * 1024), b''):
                    digest.update(block)
            name = path.name.upper()
            role = ('geometry' if name == 'GEOMETRY.BIN' else
                    'texture_candidate' if name == 'TEXTURES.BIN' or path.suffix.lower() == '.fsh' else
                    'vehicle_parameters_candidate' if name in ('GLOBALB.BUN', 'GLOBALB.LZC') else
                    'audio_candidate' if folder == 'SOUND' else
                    'cinematic_or_animation_candidate' if folder == 'NIS' else 'unclassified')
            result.append({'path': str(relative), 'bytes': path.stat().st_size,
                           'sha256': digest.hexdigest(), 'header16': head.hex(),
                           'first_u32_le': f'0x{int.from_bytes(head[:4], "little"):08x}' if len(head) >= 4 else None,
                           'role_from_name_only': role})
    return result


def cartypes(data):
    import re
    import math
    records=[]
    for match in re.finditer(rb'CARS[\\/][A-Z0-9_]+[\\/]GEOMETRY\.BIN',data):
        begin=match.start()-0x40
        if begin<0 or begin+0x890>len(data):continue
        name=data[begin:begin+16].split(b'\0')[0]
        duplicate=data[begin+0x20:begin+0x30].split(b'\0')[0]
        if not name or name!=duplicate or not re.fullmatch(rb'[A-Z0-9_]+',name):continue
        wheels=[]
        for index in range(4):
            at=begin+0x120+index*0x30
            values=[struct.unpack_from('<f',data,at+off)[0] for off in (0,8,16,0x1c)]
            if not all(math.isfinite(v) for v in values):raise ValueError('Nonfinite wheel data')
            wheels.append(dict(zip(('longitudinal','height','radius','lateral'),values)))
        mass=struct.unpack_from('<f',data,begin+0x220)[0]
        if not math.isfinite(mass):raise ValueError('Nonfinite mass')
        records.append({'name':name.decode(),'offset':begin,'record_bytes':0x890,
                        'mass_stored':mass,'wheels':wheels,'interpretation':'Candidate units from NFSU2 format reference; no physics edits'})
    return records


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--inventory', action='store_true')
    parser.add_argument('--cartypes', action='store_true')
    parser.add_argument('--map', nargs='*', default=[])
    args = parser.parse_args()
    if args.cartypes:
        records=cartypes(data_path('GLOBAL/GLOBALB.BUN').read_bytes())
        save_json('cartypes.json',records)
        print(f'Located {len(records)} validated-name CarTypeInfo candidates')
    if args.inventory:
        records = inventory()
        save_json('inventory.json', records)
        print(f'Inventoried {len(records)} data files')
    if args.map:
        reports = []
        for relative in args.map:
            data = data_path(relative).read_bytes()
            report = {'path': relative, 'sha256': hashlib.sha256(data).hexdigest(), 'coordinate_space': 'file'}
            if data.startswith(b'JDLZ'):
                data = jdlz(data)
                report['coordinate_space'] = 'decompressed memory'
                report['decompressed_bytes'] = len(data)
                report['decompressed_sha256'] = hashlib.sha256(data).hexdigest()
            try:
                report['chunks'] = chunks(data)
            except ValueError as error:
                report['unresolved'] = str(error)
            reports.append(report)
        save_json('containers.json', reports)
        print(f'Mapped {len(reports)} files; unknown layouts reported explicitly')


if __name__ == '__main__':
    main()
